namespace SimrsGramedika.Data.Master;

/// <summary>
/// First seventy-five remaining Menu M tiles: reference masters plus read-only patient and
/// clinical records that are entered through Khanza's visit workflows.
/// </summary>
public static class MenuMSpecs
{
    private static MasterField Key(string column, string label, int length) =>
        new(column, label, MaxLen: length, Key: true, Required: true);

    private static MasterField AutoId() =>
        new("id", "ID", FieldKind.Integer, Key: true, AutoKey: true);

    private static MasterSpec AutoReference(string title, string table, string nameColumn, string nameLabel) => new(
        title, table,
        [AutoId(), new(nameColumn, nameLabel, MaxLen: 30, Required: true)],
        $"SELECT id,`{nameColumn}` FROM `{table}` WHERE CONCAT_WS(' ',id,`{nameColumn}`) LIKE @p0 ORDER BY `{nameColumn}`,id",
        [("id", "ID"), (nameColumn, nameLabel)],
        $"SELECT COALESCE(MAX(id),0) FROM `{table}`", 0)
    {
        CanDelete = false,
        Hint = "Kode referensi yang sudah dipakai data pasien tidak dihapus dari layar ini.",
    };

    private static ReportSpec ReadOnly(string title, string sql, (string Column, string Header)[] columns,
        ReportPeriod period = ReportPeriod.None, string? hint = null) => new(title, sql, columns, period,
            hint ?? "Daftar baca-saja. Pencatatan dan perubahan dilakukan dari alur pelayanan Khanza.")
    { SearchWatermark = "Cari pasien atau data..." };

    private static MasterSpec TriageReference(string title, string table, string codeColumn, string codeLabel,
        string nameColumn, string nameLabel) => new(title, table,
        [Key(codeColumn, codeLabel, 3), new(nameColumn, nameLabel, MaxLen: 150, Required: true)],
        $"SELECT `{codeColumn}`,`{nameColumn}` FROM `{table}` WHERE CONCAT_WS(' ',`{codeColumn}`,`{nameColumn}`) LIKE @p0 ORDER BY `{nameColumn}`,`{codeColumn}`",
        [(codeColumn, codeLabel), (nameColumn, nameLabel)])
    { CanDelete = false, Hint = "Master triase yang sudah dipakai pada penilaian IGD tidak dihapus dari layar ini." };

    private static MasterSpec TriageScale(string title, string table, string codeColumn, string nameColumn) => new(title, table,
        [new("kode_pemeriksaan", "Pemeriksaan", FieldKind.Lookup, Required: true,
                LookupSql: "SELECT kode_pemeriksaan AS kode,nama_pemeriksaan AS nama FROM master_triase_pemeriksaan ORDER BY nama_pemeriksaan"),
         Key(codeColumn, "Kode Skala", 3), new(nameColumn, "Pengkajian", MaxLen: 150, Required: true)],
        $"SELECT s.{codeColumn},s.kode_pemeriksaan,p.nama_pemeriksaan,s.{nameColumn} FROM `{table}` s LEFT JOIN master_triase_pemeriksaan p ON p.kode_pemeriksaan=s.kode_pemeriksaan WHERE CONCAT_WS(' ',s.{codeColumn},s.kode_pemeriksaan,p.nama_pemeriksaan,s.{nameColumn}) LIKE @p0 ORDER BY p.nama_pemeriksaan,s.{nameColumn},s.{codeColumn}",
        [(codeColumn, "Kode"), ("kode_pemeriksaan", "Kode Pemeriksaan"), ("nama_pemeriksaan", "Pemeriksaan"), (nameColumn, "Pengkajian")])
    { CanDelete = false, Hint = "Pilihan skala yang sudah dipakai pada triase IGD tidak dihapus dari layar ini." };

    private static ReportSpec Soap(string title, string table, string memberTable) => ReadOnly(title,
        $"SELECT x.tgl_perawatan,x.jam_rawat,x.no_rawat,r.no_rkm_medis,p.nm_pasien,x.keluhan,x.pemeriksaan,x.penilaian,x.rtl,x.instruksi,x.evaluasi,x.tensi,x.suhu_tubuh,x.nadi,x.respirasi,x.spo2,g.nama AS petugas FROM `{table}` x JOIN reg_periksa r ON r.no_rawat=x.no_rawat JOIN `{memberTable}` m ON m.no_rkm_medis=r.no_rkm_medis LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis LEFT JOIN pegawai g ON g.nik=x.nip WHERE x.tgl_perawatan BETWEEN @p1 AND @p2 AND CONCAT_WS(' ',x.no_rawat,r.no_rkm_medis,p.nm_pasien,x.keluhan,x.pemeriksaan,x.penilaian,x.rtl,x.instruksi,x.evaluasi,g.nama) LIKE @p0 ORDER BY x.tgl_perawatan DESC,x.jam_rawat DESC",
        [("tgl_perawatan", "Tanggal"), ("jam_rawat", "Jam"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"),
         ("nm_pasien", "Pasien"), ("keluhan", "Keluhan"), ("pemeriksaan", "Pemeriksaan"), ("penilaian", "Penilaian"),
         ("rtl", "RTL"), ("instruksi", "Instruksi"), ("evaluasi", "Evaluasi"), ("tensi", "Tensi"), ("suhu_tubuh", "Suhu"),
         ("nadi", "Nadi"), ("respirasi", "Respirasi"), ("spo2", "SpO₂"), ("petugas", "Petugas")], ReportPeriod.DateRange,
        "Daftar SOAP baca-saja berdasarkan pasien TNI/POLRI. Pencatatan tetap melalui alur pelayanan Khanza.");

    private static ReportSpec NutritionRecord(string title, string table, params (string Column, string Header)[] fields)
    {
        var selected = string.Join(",", fields.Select(f => $"s.`{f.Column}` AS `{f.Column}`"));
        var searched = string.Join(",", fields.Select(f => $"s.`{f.Column}`"));
        var select = $"SELECT s.tanggal,s.no_rawat,r.no_rkm_medis,p.nm_pasien,g.nama AS petugas,{selected} FROM `{table}` s LEFT JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis LEFT JOIN petugas g ON g.nip=s.nip";
        var search = $"CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,g.nama,{searched}) LIKE @p0 ORDER BY s.tanggal DESC,s.no_rawat";
        return ReadOnly(title, $"{select} WHERE s.tanggal BETWEEN @p1 AND @p2 AND {search}",
            [("tanggal", "Tanggal"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"), ("nm_pasien", "Pasien"),
             ("petugas", "Petugas"), .. fields.Select(f => (f.Column, f.Header))], ReportPeriod.DateRange,
            "Daftar skrining/asuhan gizi baca-saja. Pengkajian dan perubahan dilakukan pada alur pelayanan Khanza.")
            with { VisitSql = $"{select} WHERE s.no_rawat=@p1 AND {search}" };
    }

    private static MasterSpec NursingProblem(string title, string table) => new(title, table,
        [Key("kode_masalah", "Kode Masalah", 3), new("nama_masalah", "Nama Masalah", MaxLen: 100)],
        $"SELECT kode_masalah,nama_masalah FROM `{table}` WHERE CONCAT_WS(' ',kode_masalah,nama_masalah) LIKE @p0 ORDER BY nama_masalah,kode_masalah",
        [("kode_masalah", "Kode"), ("nama_masalah", "Masalah Keperawatan")])
    { CanDelete = false, Hint = "Master masalah yang digunakan pada pengkajian tidak dihapus dari layar ini." };

    private static MasterSpec NursingPlan(string title, string table, string problemTable) => new(title, table,
        [new("kode_masalah", "Masalah Keperawatan", FieldKind.Lookup, Required: true,
                LookupSql: $"SELECT kode_masalah AS kode,nama_masalah AS nama FROM `{problemTable}` ORDER BY nama_masalah"),
         Key("kode_rencana", "Kode Rencana", 3), new("rencana_keperawatan", "Rencana Keperawatan", FieldKind.Memo, MaxLen: 1000, Required: true)],
        $"SELECT r.kode_rencana,r.kode_masalah,m.nama_masalah,r.rencana_keperawatan FROM `{table}` r LEFT JOIN `{problemTable}` m ON m.kode_masalah=r.kode_masalah WHERE CONCAT_WS(' ',r.kode_rencana,r.kode_masalah,m.nama_masalah,r.rencana_keperawatan) LIKE @p0 ORDER BY m.nama_masalah,r.kode_rencana",
        [("kode_rencana", "Kode Rencana"), ("kode_masalah", "Kode Masalah"), ("nama_masalah", "Masalah Keperawatan"), ("rencana_keperawatan", "Rencana")])
    { CanDelete = false, Hint = "Rencana yang sudah dipakai pada asuhan tidak dihapus dari layar ini." };

    private static ReportSpec NursingAssessment(string title, string table, params (string Column, string Header)[] fields)
    {
        var selected = string.Join(",", fields.Select(f => $"s.`{f.Column}` AS `{f.Column}`"));
        var searched = string.Join(",", fields.Select(f => $"s.`{f.Column}`"));
        var select = $"SELECT s.tanggal,s.no_rawat,r.no_rkm_medis,p.nm_pasien,{selected} FROM `{table}` s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis";
        var search = $"CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,{searched}) LIKE @p0 ORDER BY s.tanggal DESC,s.no_rawat";
        return ReadOnly(title, $"{select} WHERE s.tanggal BETWEEN @p1 AND @p2 AND {search}",
            [("tanggal", "Tanggal"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"), ("nm_pasien", "Pasien"),
             .. fields.Select(f => (f.Column, f.Header))], ReportPeriod.DateRange,
            "Pengkajian klinis baca-saja. Catatan dibuat atau diubah dari alur pelayanan Khanza.") with { VisitSql = $"{select} WHERE s.no_rawat=@p1 AND {search}" };
    }

    private static ReportSpec MedicalSpecialty(string title, string table, params (string Column, string Header)[] fields)
        => DoctorRecord(title, table, "Pengkajian medis spesialis baca-saja. Pencatatan klinis tetap melalui alur pelayanan Khanza.", fields);

    private static ReportSpec DiagnosticResult(string title, string table, params (string Column, string Header)[] fields)
        => DoctorRecord(title, table, "Hasil pemeriksaan baca-saja. Interpretasi dan perubahan tetap dilakukan pada alur pemeriksaan Khanza.", fields);

    private static ReportSpec DoctorRecord(string title, string table, string hint, (string Column, string Header)[] fields)
    {
        var selected = string.Join(",", fields.Select(f => $"s.`{f.Column}` AS `{f.Column}`"));
        var searched = string.Join(",", fields.Select(f => $"s.`{f.Column}`"));
        var select = $"SELECT s.tanggal,s.no_rawat,r.no_rkm_medis,p.nm_pasien,d.nm_dokter,{selected} FROM `{table}` s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis LEFT JOIN dokter d ON d.kd_dokter=s.kd_dokter";
        var search = $"CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,d.nm_dokter,{searched}) LIKE @p0 ORDER BY s.tanggal DESC,s.no_rawat";
        return ReadOnly(title, $"{select} WHERE s.tanggal BETWEEN @p1 AND @p2 AND {search}",
            [("tanggal", "Tanggal"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"), ("nm_pasien", "Pasien"), ("nm_dokter", "Dokter"),
             .. fields.Select(f => (f.Column, f.Header))], ReportPeriod.DateRange, hint)
             with { VisitSql = $"{select} WHERE s.no_rawat=@p1 AND {search}" };
    }

    private static ReportSpec ObservationRecord(string title, string table, params (string Column, string Header)[] fields)
    {
        var selected = string.Join(",", fields.Select(f => $"s.`{f.Column}` AS `{f.Column}`"));
        var searched = string.Join(",", fields.Select(f => $"s.`{f.Column}`"));
        var sql = $"SELECT s.tgl_perawatan,s.jam_rawat,s.no_rawat,r.no_rkm_medis,p.nm_pasien,g.nama AS petugas,{selected} FROM `{table}` s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis LEFT JOIN petugas g ON g.nip=s.nip WHERE s.tgl_perawatan BETWEEN @p1 AND @p2 AND CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,g.nama,{searched}) LIKE @p0 ORDER BY s.tgl_perawatan DESC,s.jam_rawat DESC,s.no_rawat";
        return ReadOnly(title, sql,
            [("tgl_perawatan", "Tanggal"), ("jam_rawat", "Jam"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"),
             ("nm_pasien", "Pasien"), ("petugas", "Petugas"), .. fields.Select(f => (f.Column, f.Header))], ReportPeriod.DateRange,
            "Observasi pasien baca-saja. Catatan tetap dibuat melalui alur perawatan Khanza.");
    }

    private static ReportSpec NursingNote(string title, string table) => ReadOnly(title,
        $"SELECT s.tanggal,s.jam,s.no_rawat,r.no_rkm_medis,p.nm_pasien,g.nama AS petugas,s.uraian FROM `{table}` s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis LEFT JOIN petugas g ON g.nip=s.nip WHERE s.tanggal BETWEEN @p1 AND @p2 AND CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,g.nama,s.uraian) LIKE @p0 ORDER BY s.tanggal DESC,s.jam DESC,s.no_rawat",
        [("tanggal", "Tanggal"), ("jam", "Jam"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"),
         ("nm_pasien", "Pasien"), ("petugas", "Petugas"), ("uraian", "Catatan")], ReportPeriod.DateRange,
        "Catatan keperawatan baca-saja. Entri dibuat dari alur pelayanan Khanza.");

    private static ReportSpec DeliveryRecord(string title) => ReadOnly(title,
        "SELECT s.mulai,s.selesai,s.no_rawat,r.no_rkm_medis,p.nm_pasien,d.nm_dokter,g.nama AS petugas,s.catatan,s.anak,s.status_lahir,s.apgar_score,s.bb,s.pb,s.ketuban,s.placenta,s.darah_keluar_jumlah,s.kondisi_umum FROM catatan_persalinan s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis LEFT JOIN dokter d ON d.kd_dokter=s.kd_dokter LEFT JOIN petugas g ON g.nip=s.nip WHERE s.mulai BETWEEN @p1 AND @p2 AND CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,d.nm_dokter,g.nama,s.catatan,s.status_lahir,s.apgar_score) LIKE @p0 ORDER BY s.mulai DESC,s.no_rawat",
        [("mulai", "Mulai"), ("selesai", "Selesai"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"),
         ("nm_pasien", "Pasien"), ("nm_dokter", "Dokter"), ("petugas", "Petugas"), ("catatan", "Catatan Persalinan"),
         ("anak", "Jenis Kelamin Bayi"), ("status_lahir", "Status Lahir"), ("apgar_score", "Apgar"), ("bb", "BB"),
         ("pb", "Panjang Bayi"), ("ketuban", "Ketuban"), ("placenta", "Plasenta"), ("darah_keluar_jumlah", "Jumlah Perdarahan"),
         ("kondisi_umum", "Kondisi Umum")], ReportPeriod.DateRange,
        "Catatan persalinan baca-saja berdasarkan waktu persalinan. Pencatatan tetap melalui alur persalinan Khanza.");

    private static ReportSpec ClinicalDateRecord(string title, string table, string dateColumn,
        params (string Column, string Header)[] fields)
    {
        var selected = string.Join(",", fields.Select(f => $"s.`{f.Column}` AS `{f.Column}`"));
        var searched = string.Join(",", fields.Select(f => $"s.`{f.Column}`"));
        var sql = $"SELECT s.`{dateColumn}` AS tanggal,s.no_rawat,r.no_rkm_medis,p.nm_pasien,{selected} FROM `{table}` s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis WHERE s.`{dateColumn}` BETWEEN @p1 AND @p2 AND CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,{searched}) LIKE @p0 ORDER BY s.`{dateColumn}` DESC,s.no_rawat";
        return ReadOnly(title, sql,
            [("tanggal", "Tanggal"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"), ("nm_pasien", "Pasien"),
             .. fields.Select(f => (f.Column, f.Header))], ReportPeriod.DateRange,
            "Catatan klinis baca-saja. Entri tetap dikelola melalui alur pelayanan Khanza.");
    }

    private static ReportSpec VisitRecord(string title, string table, params (string Column, string Header)[] fields)
    {
        var selected = string.Join(",", fields.Select(f => $"s.`{f.Column}` AS `{f.Column}`"));
        var searched = string.Join(",", fields.Select(f => $"s.`{f.Column}`"));
        var sql = $"SELECT r.tgl_registrasi AS tanggal,s.no_rawat,r.no_rkm_medis,p.nm_pasien,{selected} FROM `{table}` s JOIN reg_periksa r ON r.no_rawat=s.no_rawat LEFT JOIN pasien p ON p.no_rkm_medis=r.no_rkm_medis WHERE r.tgl_registrasi BETWEEN @p1 AND @p2 AND CONCAT_WS(' ',s.no_rawat,r.no_rkm_medis,p.nm_pasien,{searched}) LIKE @p0 ORDER BY r.tgl_registrasi DESC,s.no_rawat";
        return ReadOnly(title, sql,
            [("tanggal", "Tanggal Kunjungan"), ("no_rawat", "No. Rawat"), ("no_rkm_medis", "No. RM"), ("nm_pasien", "Pasien"),
             .. fields.Select(f => (f.Column, f.Header))], ReportPeriod.DateRange,
            "Data rencana pemulangan baca-saja berdasarkan tanggal registrasi. Perubahan dilakukan melalui alur rawat inap Khanza.");
    }

